def transform(grid):
    h, w = len(grid), len(grid[0])
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            a, b = grid[:r], grid[r + 1:]
            return [[2 if x != 0 and y != 0 else 0 for x, y in zip(row_a, row_b)]
                    for row_a, row_b in zip(a, b)]
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != 0:
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
            return [[2 if x != 0 and y != 0 else 0 for x, y in zip(row_a, row_b)]
                    for row_a, row_b in zip(a, b)]
    raise ValueError('No uniform divider found')
